  ('rodice-oznameni-fromulare-nenech-to-byt', 'rodice-oznameni-fromulare', 'Nenech to být', 'https://www.nntb.cz/', ARRAY['Internetový systém sloužící k odhalování šikany a vylučování kolektivu na školách'], NULL, 68),
  ('rodice-oznameni-fromulare-co-delat-kdyz', 'rodice-oznameni-fromulare', 'Co dělat, když...', '/dokument/Co_delat.pdf', ARRAY['Průvodce nežádoucími sociálními jevy a možnostmi jejich řešení pro rodiče žáků základních škol.'], 'Obsah: Podílíme se na výchově vašich dětí (přehled kontaktů). Co děti potřebují? Jaká mají práva a povinnosti? Co potřebují rodiče? Jaká mají práva a jaké povinnosti? Jak se projevuje nežádoucí chování dětí? Co dělat, když se moje dítě „nemožně“ chová? Co dělat, když moje dítě má nevhodné kamarády? Co dělat, když moje dítě chodí za školu? Co dělat, když je moje dítě šikanováno nebo šikanuje? Co dělat, když moje dítě kouří, pije alkohol nebo zkouší drogy? Co dělat, když moje dítě podléhá počítači, televizi a mobilu? Co dělat, když si moje dítě ubližuje? Literatura.', 69),
